
const DBKEY='hawraz_offline_v1';
const EMPTY={schemaVersion:1,settings:{currency:'IRT',language:'fa',lowStock:3,backupReminderDays:7,theme:'teal',fontScale:100,iconScale:100,background:'gradient',iconStyle:'rounded',companyName:'هەوراز',companyPhone:'',companyAddress:'',taxId:''},products:[],customers:[],orders:[],payments:[],expenses:[],accounts:[{id:'cash',name:'صندوق نقدی',type:'cash',opening:0}],tools:[],suppliers:[],reminders:[],tasks:[],audit:[]};
let db, page='dashboard', editId=null, editOrderId=null;
const $=id=>document.getElementById(id);
const uid=()=>crypto.randomUUID();
const today=()=>new Date().toISOString().slice(0,10);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>{const n=Number(v);if(!Number.isSafeInteger(n)||n<0)throw Error('مبلغ باید عدد صحیح و مثبت باشد.');return n};
const fmt=n=>`${Number(n||0).toLocaleString('fa-IR')} ${db.settings.currency==='IRR'?'ریال':'تومان'}`;
const sum=(arr,fn)=>arr.reduce((a,x)=>a+Number(fn(x)||0),0);
const toast=m=>{const el=$('toast');el.textContent=m;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)};
const save=async()=>{await new Promise((resolve,reject)=>{const tx=IDB.transaction('workspace','readwrite');tx.objectStore('workspace').put(db,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('ذخیره‌سازی ناموفق'))});};
let IDB;
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DBKEY,1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function init(){IDB=await openDB();db=await new Promise((resolve,reject)=>{const q=IDB.transaction('workspace','readonly').objectStore('workspace').get('main');q.onsuccess=()=>resolve({...structuredClone(EMPTY),...(q.result||{})});q.onerror=()=>reject(q.error)});Object.keys(EMPTY).forEach(k=>{if(!db[k])db[k]=structuredClone(EMPTY[k])});if(!db.settings)db.settings=structuredClone(EMPTY.settings);if(!db.tasks)db.tasks=[];if(!db.settings.authSalt||!db.settings.authHash){const h=await makePasswordHash('123454321');db.settings.authSalt=h.salt;db.settings.authHash=h.hash;await save()}applyAppearance();if(sessionStorage.getItem('hawraz_unlocked')==='yes')render();else renderLock();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}

const enc64=b=>btoa(String.fromCharCode(...new Uint8Array(b)));
async function makePasswordHash(password,saltText){const salt=saltText?Uint8Array.from(atob(saltText),c=>c.charCodeAt(0)):crypto.getRandomValues(new Uint8Array(16));const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},material,256);return {salt:enc64(salt),hash:enc64(bits)}}
async function checkPassword(password){const h=await makePasswordHash(password,db.settings.authSalt);return h.hash===db.settings.authHash}
function renderLock(){document.querySelector('.lock-screen')?.remove();const el=document.createElement('div');el.className='lock-screen';el.innerHTML=`<form id="unlock-form" class="lock-card"><img src="./icon.svg" alt="HAWRAZ"><small>WORKSHOP MANAGEMENT</small><h1>ورود به هەوراز</h1><p>برای ورود، رمز عبور را وارد کن.</p><input name="password" type="password" autocomplete="current-password" placeholder="رمز عبور" required autofocus><button class="primary">ورود</button><small class="muted">دسترسی محلی به برنامه</small></form>`;document.body.appendChild(el);$('unlock-form').onsubmit=async e=>{e.preventDefault();const pass=new FormData(e.currentTarget).get('password');if(await checkPassword(pass)){sessionStorage.setItem('hawraz_unlocked','yes');el.remove();render()}else toast('رمز عبور نادرست است.')};}
function applyAppearance(){if(!db?.settings)return;const palettes={teal:['#35d6c5','#087e83','#176b9c'],blue:['#69a9ff','#245cb5','#173e80'],purple:['#c4a3ff','#7046b5','#4b337f'],amber:['#f5c66b','#a86a14','#70460e'],rose:['#ff9db7','#ad3b65','#762847']};const p=palettes[db.settings.theme]||palettes.teal;document.documentElement.style.setProperty('--cyan',p[0]);document.documentElement.style.setProperty('--accent-a',p[1]);document.documentElement.style.setProperty('--accent-b',p[2]);document.documentElement.style.setProperty('--font-scale',(Number(db.settings.fontScale)||100)/100);document.documentElement.style.setProperty('--icon-scale',(Number(db.settings.iconScale)||100)/100);const bgs={gradient:'radial-gradient(ellipse at 80% 0,#164052,transparent 38%),#081522',plain:'#081522',light:'#e9f0f4',forest:'radial-gradient(ellipse at 80% 0,#234b3c,transparent 38%),#0b1b17',sand:'radial-gradient(ellipse at 80% 0,#66543b,transparent 38%),#211b14'};document.body.style.background=bgs[db.settings.background]||bgs.gradient;if(db.settings.background==='light'){document.body.classList.add('light-mode')}else document.body.classList.remove('light-mode');document.body.classList.remove('icon-style-rounded','icon-style-square','icon-style-minimal');document.body.classList.add('icon-style-'+(db.settings.iconStyle||'rounded'));}
