function translateDom(){const lang=db.settings.language||'fa',dict=LANG[lang];if(!dict)return;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){let v=n.nodeValue.trim();if(dict[v])n.nodeValue=n.nodeValue.replace(v,dict[v]);}document.documentElement.lang=lang;document.documentElement.dir=['fa','ar','ku'].includes(lang)?'rtl':'ltr';}
function printCurrent(){window.print()}
function drawReportChart(){const c=$('report-chart');if(!c)return;const ctx=c.getContext('2d'),type=$('chart-type')?.value||'bar',metric=$('chart-metric')?.value||'sales';const rows=db.orders.filter(o=>o.status!=='cancelled').slice(-8);const vals=rows.map(o=>({label:o.code.slice(-4),value:metric==='profit'?Number(o.profit??(o.total-o.productionCost)):metric==='cost'?Number(o.productionCost||0):Number(o.total||0)}));ctx.clearRect(0,0,c.width,c.height);if(!vals.length){ctx.fillStyle='#91aab8';ctx.fillText('برای نمایش نمودار، سفارش ثبت کن.',20,35);return}const max=Math.max(1,...vals.map(x=>x.value));const color=getComputedStyle(document.documentElement).getPropertyValue('--cyan').trim()||'#35d6c5';if(type==='pie'){const total=vals.reduce((a,x)=>a+x.value,0)||1;let a=-Math.PI/2;vals.forEach((v,i)=>{const b=a+v.value/total*Math.PI*2;ctx.beginPath();ctx.moveTo(300,130);ctx.arc(300,130,95,a,b);ctx.closePath();ctx.fillStyle=`hsl(${170+i*37} 65% 55%)`;ctx.fill();a=b});}else if(type==='line'){ctx.beginPath();vals.forEach((v,i)=>{const x=35+i*(530/Math.max(1,vals.length-1)),y=225-v.value/max*175;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle=color;ctx.lineWidth=4;ctx.stroke();vals.forEach((v,i)=>{const x=35+i*(530/Math.max(1,vals.length-1)),y=225-v.value/max*175;ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()})}else{const w=500/vals.length;vals.forEach((v,i)=>{const h=v.value/max*175;ctx.fillStyle=color;ctx.fillRect(35+i*w,225-h,Math.max(10,w-12),h);ctx.fillStyle='#9bb2bd';ctx.font='11px Tahoma';ctx.fillText(v.label,35+i*w,245)})}ctx.fillStyle='#a8bec9';ctx.font='12px Tahoma';ctx.fillText('مبالغ سفارش‌های اخیر',20,18)}

function audit(action,kind,id,detail=''){db.audit.unshift({id:uid(),at:new Date().toISOString(),action,kind,recordId:id,detail});db.audit=db.audit.slice(0,2000)}
function orderTotal(o){return Number(o.total||0)}
function paidFor(customerId){return sum(db.payments.filter(p=>p.customerId===customerId&&p.kind==='receipt'),p=>p.amount)-sum(db.payments.filter(p=>p.customerId===customerId&&p.kind==='refund'),p=>p.amount)}
function customerOrders(id){return db.orders.filter(o=>o.customerId===id&&o.status!=='cancelled')}
function customerBalance(id){return sum(customerOrders(id),o=>o.total)-paidFor(id)}
function accountBalance(id){const a=db.accounts.find(x=>x.id===id);return Number(a?.opening||0)+sum(db.payments.filter(p=>p.accountId===id),p=>p.kind==='receipt'?p.amount:p.kind==='refund'?-p.amount:p.kind==='deposit'?p.amount:p.kind==='withdrawal'?-p.amount:0)-sum(db.expenses.filter(x=>x.accountId===id),x=>x.amount)}
function statusName(s){return ({registered:'ثبت‌شده',production:'در حال ساخت',ready:'آماده تحویل',delivered:'تحویل‌شده',cancelled:'لغوشده'})[s]||s}
function table(head,rows){return rows.length?`<div class="tablewrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">هنوز اطلاعاتی ثبت نشده است.</div>`}
function stat(label,value){return `<article class="stat"><span>${label}</span><strong>${value}</strong></article>`}
function panel(title,body){return `<section class="panel"><h2>${title}</h2>${body}</section>`}
function field(label,name,type='text',required=false,extra=''){return `<label>${label}<input name="${name}" type="${type}" ${required?'required':''} ${extra}></label>`}
function select(label,name,options,required=false){return `<label>${label}<select name="${name}" ${required?'required':''}>${options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}</select></label>`}
function form(id,fields,button='ذخیره'){return `<form class="form" id="${id}">${fields}<div class="span2"><button class="primary" type="submit">${button}</button> <button type="button" class="ghost" data-clear="${id}">پاک‌کردن فرم</button></div></form>`}
function nav(){const items=[['dashboard','داشبورد'],['search','جستجو'],['products','محصولات و انبار'],['customers','مشتریان'],['orders','سفارش‌ها و پروژه‌ها'],['finance','مالی، صندوق و بانک'],['expenses','هزینه‌ها'],['tools','ابزارهای کارگاه'],['suppliers','تأمین‌کنندگان'],['reminders','تقویم و یادآوری'],['tasks','کارهای کارگاه'],['reports','گزارش‌ها'],['settings','تنظیمات و پشتیبان']];$('nav').innerHTML=items.map(([k,v])=>`<button data-page="${k}" class="${page===k?'active':''}">${v}</button>`).join('')}
function alerts(){let a=[];db.products.filter(p=>Number(p.quantity)<=Number(db.settings.lowStock)).forEach(p=>a.push({s:`موجودی ${p.name} کم است (${p.quantity})`,red:true}));db.orders.filter(o=>o.dueDate&&o.dueDate<today()&&!['delivered','cancelled'].includes(o.status)).forEach(o=>a.push({s:`موعد سفارش ${o.code} گذشته است`,red:true}));db.reminders.filter(x=>!x.done&&x.date<=today()).forEach(x=>a.push({s:`یادآوری: ${x.title}`}));$('alerts').innerHTML=a.slice(0,6).map(x=>`<div class="alert ${x.red?'red':''}">${esc(x.s)}</div>`).join('')}
function dashboard(){const sales=sum(db.orders.filter(o=>o.status!=='cancelled'),o=>o.total),receivable=sum(db.customers,c=>Math.max(0,customerBalance(c.id))),stock=sum(db.products,p=>p.quantity*p.buyPrice),active=db.orders.filter(o=>!['delivered','cancelled'].includes(o.status)).length,profit=sum(db.orders.filter(o=>o.status!=='cancelled'),o=>Number(o.profit??(o.total-o.productionCost)));const overdue=db.orders.filter(o=>o.dueDate&&o.dueDate<today()&&!['delivered','cancelled'].includes(o.status)).length,low=db.products.filter(p=>Number(p.quantity)<=Number(db.settings.lowStock)).length;return `<div class="hero"><small>HAWRAZ / WORKSHOP INTELLIGENCE</small><h2>مدیریت روشن‌تر، ساخت دقیق‌تر.</h2><p>مرکز کنترل سفارش‌ها، مشتریان، موجودی، سود و جریان مالی کارگاه.</p></div><div class="stats">${stat('فروش سفارش‌ها',fmt(sales))}${stat('سود تخمینی',fmt(profit))}${stat('طلب از مشتریان',fmt(receivable))}${stat('ارزش خرید موجودی',fmt(stock))}${stat('سفارش‌های باز',active)}${stat('موعدهای گذشته',overdue)}${stat('کالاهای کم‌موجود',low)}${stat('تعداد مشتریان',db.customers.length)}</div><div class="grid">${panel('آخرین سفارش‌ها',table(['کد','تاریخ','مشتری','شرح','مبلغ','سود','وضعیت'],db.orders.slice(-8).reverse().map(o=>[esc(o.code),esc(o.orderDate||o.createdAt?.slice(0,10)||''),esc(db.customers.find(c=>c.id===o.customerId)?.name||'مشتری حذف‌شده'),esc(o.title),fmt(o.total),fmt(o.profit??(o.total-o.productionCost)),statusName(o.status)])))}${panel('نمای سریع',`<div class="notice">این نسخه آفلاین است و اطلاعات در همین دستگاه ذخیره می‌شود. برای انتقال دستگاه‌ها از پشتیبان رمزگذاری‌شده استفاده کن.</div><p>محصولات: <b>${db.products.length}</b></p><p>مشتریان: <b>${db.customers.length}</b></p><p>سفارش‌ها: <b>${db.orders.length}</b></p><p>کارهای باز: <b>${(db.tasks||[]).filter(t=>t.status!=='done').length}</b></p><p>حساب‌ها: <b>${db.accounts.length}</b></p><button class="ghost" onclick="printCurrent()">چاپ داشبورد</button>`)}</div>`}
function products(){return `<div class="grid">${panel(editId?'ویرایش محصول':'ثبت محصول',form('product-form',field('نام محصول','name','text',true)+field('کد کالا / SKU','sku')+select('دسته‌بندی','category',[['چوبی','چوبی'],['الکترونیکی','الکترونیکی'],['رباتیک','رباتیک'],['فلزی','فلزی'],['سفارشی','سفارشی']])+field('موجودی','quantity','number',true,'min="0" step="1"')+field('قیمت خرید واحد','buyPrice','number',true,'min="0" step="1"')+field('قیمت فروش واحد','sellPrice','number',true,'min="0" step="1"')))}${panel('فهرست محصولات',table(['کد','نام','دسته','موجودی','خرید','فروش','عملیات'],db.products.map(p=>[esc(p.sku),esc(p.name),esc(p.category),p.quantity,fmt(p.buyPrice),fmt(p.sellPrice),`<button class="mini" data-edit="product" data-id="${p.id}">ویرایش</button> <button class="mini danger" data-del="product" data-id="${p.id}">حذف</button>`])))}</div>`}
function customers(){return `<div class="grid">${panel('ثبت مشتری',form('customer-form',field('نام و نام خانوادگی','name','text',true)+field('شماره موبایل','phone')+`<label class="span2">آدرس<textarea name="address" rows="2"></textarea></label><label class="span2">یادداشت<textarea name="note" rows="2"></textarea></label>`))}${panel('دفتر مشتریان',table(['نام','موبایل','سفارش','جمع خرید','مانده حساب','عملیات'],db.customers.map(c=>[esc(c.name),esc(c.phone),customerOrders(c.id).length,fmt(sum(customerOrders(c.id),o=>o.total)),fmt(customerBalance(c.id)),`<button class="mini" data-edit="customer" data-id="${c.id}">ویرایش</button>`])))}</div>`}
function orders(){const customerOpts=[['','انتخاب مشتری'],...db.customers.map(c=>[c.id,c.name])];const productOpts=[['','سفارش اختصاصی / بدون محصول'],...db.products.map(p=>[p.id,`${p.name} (موجودی ${p.quantity})`])];const old=editOrderId?db.orders.find(x=>x.id===editOrderId):null;const f=(label,name,type='text',req=false,extra='')=>field(label,name,type,req,extra);return `<div class="grid">${panel(old?'ویرایش سفارش':'ثبت سفارش جدید',form('order-form',select('مشتری','customerId',customerOpts,true)+select('محصول (اختیاری)','productId',productOpts)+f('شرح سفارش','title','text',true)+f('تاریخ سفارش','orderDate','date',true,`value="${old?.orderDate||today()}"`)+f('تعداد','quantity','number',true,`min="1" step="1" value="${old?.quantity||1}"`)+f('قیمت واحد','unitPrice','number',true,`min="0" step="1" value="${old?.unitPrice||''}"`)+f('درصد تخفیف دستی','discountPercent','number',false,`min="0" max="100" step="0.01" value="${old?.discountPercent??(old&&old.subtotal?old.discount/old.subtotal*100:0)}"`)+f('هزینه ساخت کل','productionCost','number',false,`min="0" step="1" value="${old?.productionCost||0}"`)+f('تاریخ تحویل سفارش','dueDate','date')+select('وضعیت','status',[['registered','ثبت‌شده'],['production','در حال ساخت'],['ready','آماده تحویل'],['delivered','تحویل‌شده'],['cancelled','لغوشده']])+(!old?f('پیش‌پرداخت','initialPayment','number',false,'min="0" step="1" value="0"'):'<div class="span2 muted">پیش‌پرداخت ثبت‌شده در ویرایش سفارش تغییر نمی‌کند؛ دریافت جدید را از بخش مالی ثبت کن.</div>')+`<div class="span2 notice" id="order-calculation">جمع جزء، تخفیف، مبلغ نهایی و سود پس از ورود مقادیر محاسبه می‌شود.</div>` ,old?'ذخیره ویرایش':'ثبت سفارش'))}${panel('پیگیری سفارش‌ها',table(['کد','تاریخ','مشتری','شرح','تعداد','مبلغ نهایی','سود','موعد تحویل','وضعیت','عملیات'],db.orders.map(o=>[esc(o.code),esc(o.orderDate||o.createdAt?.slice(0,10)||''),esc(db.customers.find(c=>c.id===o.customerId)?.name),esc(o.title),o.quantity,fmt(o.total),fmt(o.profit??(o.total-o.productionCost)),esc(o.dueDate),statusName(o.status),`<button class="mini" data-edit-order="${o.id}">ویرایش</button> <button class="mini" data-invoice="${o.id}">فاکتور / چاپ</button> <button class="mini" data-status="${o.id}">وضعیت</button>`])))}</div>`}
function finance(){return `<div class="stats">${stat('موجودی کل حساب‌ها',fmt(sum(db.accounts,a=>accountBalance(a.id))))}${stat('دریافت‌های مشتریان',fmt(sum(db.payments.filter(p=>p.kind==='receipt'),p=>p.amount)))}${stat('بازپرداخت به مشتری',fmt(sum(db.payments.filter(p=>p.kind==='refund'),p=>p.amount)))}</div><div class="grid">${panel('ثبت دریافت / بازپرداخت',form('payment-form',select('مشتری','customerId',[['','انتخاب مشتری'],...db.customers.map(c=>[c.id,c.name])],true)+select('مرتبط با سفارش (اختیاری)','orderId',[['','بدون ارتباط'],...db.orders.map(o=>[o.id,`${o.code} - ${o.title}`])])+select('نوع تراکنش','kind',[['receipt','دریافت از مشتری'],['refund','بازپرداخت به مشتری']],true)+select('حساب','accountId',db.accounts.map(a=>[a.id,a.name]),true)+field('مبلغ','amount','number',true,'min="1" step="1"')+field('تاریخ','date','date',true,`value="${today()}"`)+field('شرح','description')))}${panel('حساب‌ها و موجودی',form('account-form',field('عنوان حساب','name','text',true)+select('نوع حساب','type',[['cash','صندوق نقدی'],['bank','بانک'],['other','سایر']])+field('موجودی افتتاحیه','opening','number',false,'min="0" step="1" value="0"') )+table(['حساب','نوع','موجودی','عملیات'],db.accounts.map(a=>[esc(a.name),a.type==='cash'?'صندوق':a.type==='bank'?'بانک':'سایر',fmt(accountBalance(a.id)),a.id==='cash'?'پیش‌فرض':`<button class="mini danger" data-del="account" data-id="${a.id}">حذف</button>`])))}</div><div class="panel"><h2>تاریخچه تراکنش‌های مشتری</h2>${table(['تاریخ','مشتری','نوع','حساب','مبلغ','شرح'],db.payments.slice().reverse().map(p=>[p.date,esc(db.customers.find(c=>c.id===p.customerId)?.name),p.kind==='receipt'?'دریافت':'بازپرداخت',esc(db.accounts.find(a=>a.id===p.accountId)?.name),fmt(p.amount),esc(p.description)]))}</div>`}
function expenses(){return `<div class="grid">${panel('ثبت هزینه',form('expense-form',field('شرح هزینه','title','text',true)+field('مبلغ','amount','number',true,'min="1" step="1"')+select('پرداخت از حساب','accountId',db.accounts.map(a=>[a.id,a.name]),true)+field('تاریخ','date','date',true,`value="${today()}"`)+select('دسته','category',[['material','مواد اولیه'],['transport','حمل‌ونقل'],['repair','تعمیرات'],['other','سایر']])))}${panel('فهرست هزینه‌ها',table(['تاریخ','شرح','دسته','حساب','مبلغ'],db.expenses.slice().reverse().map(x=>[x.date,esc(x.title),esc(x.category),esc(db.accounts.find(a=>a.id===x.accountId)?.name),fmt(x.amount)])))}</div>`}
function tools(){return `<div class="grid">${panel('ثبت ابزار',form('tool-form',field('نام ابزار','name','text',true)+field('برند / مدل','model')+field('شماره سریال','serial')+field('تاریخ خرید','purchaseDate','date')+field('قیمت خرید','price','number',false,'min="0" step="1"')+field('محل نگهداری','location')+select('وضعیت','status',[['available','موجود'],['broken','خراب'],['repair','در تعمیر'],['retired','خارج از کارگاه']])+field('تاریخ سرویس بعدی','nextService','date')))}${panel('ابزارهای ثبت‌شده',table(['نام','مدل','وضعیت','سرویس بعدی'],db.tools.map(x=>[esc(x.name),esc(x.model),({available:'موجود',broken:'خراب',repair:'در تعمیر',retired:'خارج از کارگاه'})[x.status],esc(x.nextService)])))}</div>`}
function suppliers(){return `<div class="grid">${panel('ثبت تأمین‌کننده',form('supplier-form',field('نام فروشنده','name','text',true)+field('شماره تماس','phone')+field('آدرس','address')+field('نوع کالا','goods')))}${panel('دفتر تأمین‌کنندگان',table(['نام','تماس','آدرس','نوع کالا'],db.suppliers.map(s=>[esc(s.name),esc(s.phone),esc(s.address),esc(s.goods)])))}</div>`}
function reminders(){return `<div class="grid">${panel('یادآوری جدید',form('reminder-form',field('عنوان یادآوری','title','text',true)+field('تاریخ','date','date',true,`value="${today()}"`)+field('ساعت','time','time')+field('یادداشت','note')))}${panel('فهرست یادآوری‌ها',table(['تاریخ','ساعت','عنوان','وضعیت','عملیات'],db.reminders.map(x=>[x.date,x.time||'—',esc(x.title),x.done?'انجام‌شده':'در انتظار',`<button class="mini" data-done="${x.id}">تغییر وضعیت</button>`])))}</div><div class="notice">یادآوری‌های داخل برنامه هنگام باز بودن برنامه قابل مشاهده‌اند. نمایش اعلان دقیق در زمان بسته بودن برنامه به محدودیت‌های سیستم‌عامل و مرورگر بستگی دارد و در این نسخه تضمین نمی‌شود.</div>`}
function tasks(){return `<div class="grid">${panel('ثبت کار جدید',form('task-form',field('عنوان کار','title','text',true)+field('مسئول','assignee')+field('مهلت انجام','dueDate','date')+select('اولویت','priority',[['normal','عادی'],['high','بالا'],['urgent','فوری']])+select('وضعیت','status',[['open','باز'],['doing','در حال انجام'],['done','انجام‌شده']])+`<label class="span2">توضیحات<textarea name="note" rows="2"></textarea></label>`))}${panel('تابلوی کارهای کارگاه',table(['عنوان','مسئول','مهلت','اولویت','وضعیت','عملیات'],(db.tasks||[]).map(t=>[esc(t.title),esc(t.assignee),esc(t.dueDate),({normal:'عادی',high:'بالا',urgent:'فوری'})[t.priority],({open:'باز',doing:'در حال انجام',done:'انجام‌شده'})[t.status],`<button class="mini" data-task-done="${t.id}">تغییر وضعیت</button> <button class="mini danger" data-task-del="${t.id}">حذف</button>`])))}</div>`}
function reports(){const valid=db.orders.filter(o=>o.status!=='cancelled'),revenue=sum(valid,o=>o.total),cost=sum(valid,o=>o.productionCost),expensesTotal=sum(db.expenses,x=>x.amount),gross=sum(valid,o=>Number(o.profit??(o.total-o.productionCost)))-expensesTotal;return `<div class="stats">${stat('فروش سفارش‌ها',fmt(revenue))}${stat('هزینه ساخت',fmt(cost))}${stat('هزینه‌های ثبت‌شده',fmt(expensesTotal))}${stat('سود تخمینی پس از هزینه‌ها',fmt(gross))}</div><div class="panel"><div class="toolbar"><label>نوع نمودار <select id="chart-type"><option value="bar">ستونی</option><option value="pie">دایره‌ای</option><option value="line">خطی</option></select></label><label>شاخص <select id="chart-metric"><option value="sales">فروش</option><option value="profit">سود</option><option value="cost">هزینه ساخت</option></select></label><button class="ghost" onclick="printCurrent()">چاپ گزارش</button></div><h2>نمودار سفارش‌ها</h2><canvas id="report-chart" width="600" height="270" style="width:100%;max-width:760px;height:270px"></canvas><p class="muted">نمودار بر اساس مبلغ ۸ سفارش اخیر ساخته می‌شود؛ سود نهایی برآوردی است و به ثبت دقیق همه هزینه‌ها بستگی دارد.</p></div><div class="grid">${panel('مشتریان بر اساس مجموع سفارش',table(['مشتری','تعداد سفارش','مجموع خرید','مانده'],db.customers.map(c=>[esc(c.name),customerOrders(c.id).length,fmt(sum(customerOrders(c.id),o=>o.total)),fmt(customerBalance(c.id))])))}${panel('محصولات و ارزش موجودی',table(['محصول','تعداد','ارزش خرید موجودی'],db.products.map(p=>[esc(p.name),p.quantity,fmt(p.quantity*p.buyPrice)])))}</div><button class="primary" data-csv="orders">خروجی CSV سفارش‌ها</button> <button class="ghost" data-csv="customers">خروجی CSV مشتریان</button> <button class="ghost" onclick="printCurrent()">چاپ همه گزارش</button>`}
function settings(){return `<div class="grid">${panel('شخصی‌سازی ظاهر',`<form id="settings-form" class="form">${select('واحد پول','currency',[['IRT','تومان'],['IRR','ریال']])}${field('آستانه هشدار موجودی','lowStock','number',true,'min="0" step="1"')}${select('زبان برنامه','language',[['fa','فارسی'],['ku','کوردی سۆرانی'],['ar','العربية'],['en','English'],['zh','中文']])}${select('طیف رنگی','theme',[['teal','فیروزه‌ای'],['blue','آبی'],['purple','بنفش'],['amber','کهربایی'],['rose','صورتی']])}${select('پس‌زمینه','background',[['gradient','گرادیانی تیره'],['plain','تیره ساده'],['forest','سبز جنگلی'],['sand','قهوه‌ای'],['light','روشن']])}${select('سبک آیکون‌ها','iconStyle',[['rounded','گرد'],['square','گوشه‌دار'],['minimal','ساده']])}<label>اندازه نوشته <input name="fontScale" type="range" min="85" max="125" step="5" value="${db.settings.fontScale||100}"></label><label>اندازه آیکون <input name="iconScale" type="range" min="80" max="150" step="10" value="${db.settings.iconScale||100}"></label><div class="span2"><button class="primary">ذخیره ظاهر و تنظیمات</button></div></form><p class="muted">ترجمه بخش‌های اصلی در زبان‌های انتخابی فعال است؛ برخی توضیحات تخصصی ممکن است همچنان فارسی باشند.</p>`)}${panel('مشخصات کسب‌وکار برای فاکتور',`<form id="business-form" class="form">${field('نام کسب‌وکار','companyName','text',true)}${field('شماره تماس','companyPhone')}${field('شناسه / کد مالیاتی','taxId')}<label class="span2">نشانی<textarea name="companyAddress" rows="2">${esc(db.settings.companyAddress||'')}</textarea></label><div class="span2"><button class="primary">ذخیره مشخصات فاکتور</button></div></form><p class="muted">قالب فاکتور رسمی‌نما و قابل چاپ است؛ رسمی بودن مالیاتی آن به قوانین محل فعالیت و اطلاعات ثبت‌شده بستگی دارد.</p>`)}${panel('تغییر رمز ورود',`<form id="password-form" class="form">${field('رمز فعلی','currentPassword','password',true)}${field('رمز جدید','newPassword','password',true,'minlength="8"')}${field('تکرار رمز جدید','confirmPassword','password',true,'minlength="8"')}<div class="span2"><button class="primary">تغییر رمز</button></div></form><div class="notice">رمز پیش‌فرض اولیه 123454321 است. این قفل محلی برای جلوگیری از ورود معمولی است و جایگزین احراز هویت سروری یا محافظت در برابر دسترسی فنی به دستگاه نیست.</div>`)}${panel('پشتیبان‌گیری و بازیابی',`<p>از تمام اطلاعات همین دستگاه فایل JSON بگیر و آن را در دو محل امن نگه دار.</p><button class="primary" id="backup2">دانلود پشتیبان JSON</button> <button class="ghost" id="backup-encrypted">پشتیبان رمزگذاری‌شده</button> <label class="ghost" style="display:inline-block">بازیابی پشتیبان<input id="restore" type="file" accept=".json,application/json" hidden></label><p class="muted">بازیابی، اطلاعات فعلی این دستگاه را با فایل پشتیبان جایگزین می‌کند. قبل از بازیابی پشتیبان بگیر.</p>`)}${panel('وضعیت سامانه',`<div class="notice">نسخه فعلی آفلاین است؛ همگام‌سازی ابری بین دستگاه‌ها فعال نیست. اطلاعات مشتریان و مالی را فقط روی دستگاه امن نگه دار.</div><p>محصولات ${db.products.length} · مشتریان ${db.customers.length} · سفارش‌ها ${db.orders.length} · پرداخت‌ها ${db.payments.length} · کارها ${(db.tasks||[]).length}</p>`)}</div><div class="panel"><h2>سوابق تغییرات اخیر</h2>${table(['زمان','عملیات','بخش','شناسه'],db.audit.slice(0,30).map(a=>[a.at.slice(0,19).replace('T',' '),esc(a.action),esc(a.kind),esc(a.recordId)]))}</div>`}
function searchPage(){return `<div class="panel"><h2>جستجوی سراسری هەوراز</h2><p class="muted">نام مشتری، شماره تماس، کد سفارش، نام محصول، کد کالا، شرح سفارش، تأمین‌کننده، ابزار، هزینه یا عنوان کار را جستجو کن.</p><div class="toolbar"><input id="global-search" type="search" placeholder="عبارت مورد نظر را بنویس…" autocomplete="off" aria-label="جستجو در همه اطلاعات"><select id="search-category"><option value="all">همه بخش‌ها</option><option value="products">محصولات</option><option value="customers">مشتریان</option><option value="orders">سفارش‌ها</option><option value="expenses">هزینه‌ها</option><option value="suppliers">تأمین‌کنندگان</option><option value="tools">ابزارها</option><option value="tasks">کارها</option><option value="reminders">یادآوری‌ها</option></select><button class="ghost" id="clear-search">پاک‌کردن</button></div><div id="search-results"><div class="empty">برای شروع، عبارت جستجو را وارد کن.</div></div></div>`}
function searchRecords(query,category='all'){
 const q=String(query||'').trim().toLocaleLowerCase();if(!q)return [];
 const groups=[
  ['products','محصول',db.products,p=>[p.name,p.sku,p.category,p.quantity,p.buyPrice,p.sellPrice]],
  ['customers','مشتری',db.customers,c=>[c.name,c.phone,c.address,c.note]],
  ['orders','سفارش',db.orders,o=>[o.code,o.title,o.orderDate,o.dueDate,o.status,db.customers.find(c=>c.id===o.customerId)?.name,o.quantity,o.total]],
  ['expenses','هزینه',db.expenses,x=>[x.title,x.description,x.date,x.amount,x.category]],
  ['suppliers','تأمین‌کننده',db.suppliers,x=>[x.name,x.phone,x.address,x.note]],
  ['tools','ابزار',db.tools,x=>[x.name,x.code,x.description,x.price]],
  ['tasks','کار',db.tasks||[],x=>[x.title,x.assignee,x.priority,x.dueDate,x.status]],
  ['reminders','یادآوری',db.reminders,x=>[x.title,x.date,x.note]]
 ];
 const out=[];for(const [kind,label,items,fields] of groups){if(category!=='all'&&category!==kind)continue;for(const item of items){const hay=fields(item).filter(v=>v!==undefined&&v!==null).join(' ').toLocaleLowerCase();if(hay.includes(q)){const title=item.name||item.title||item.code||label;const detail=kind==='orders'?`${item.code||''} · ${db.customers.find(c=>c.id===item.customerId)?.name||'بدون مشتری'} · ${fmt(item.total||0)}`:kind==='products'?`کد: ${item.sku||'—'} · موجودی: ${item.quantity??'—'}`:kind==='customers'?`${item.phone||'بدون شماره'} · ${item.address||''}`:kind==='tasks'?`${item.assignee||'بدون مسئول'} · ${item.dueDate||''}`:kind==='reminders'?`${item.date||''}`:kind==='expenses'?`${item.date||''} · ${fmt(item.amount||0)}`:`${item.phone||item.code||item.category||''}`;out.push({kind,label,title,detail,id:item.id})}}}
 return out.slice(0,100);
}
function drawSearchResults(){const box=$('search-results');if(!box)return;const q=$('global-search')?.value||'',cat=$('search-category')?.value||'all';if(!q.trim()){box.innerHTML='<div class="empty">برای شروع، عبارت جستجو را وارد کن.</div>';return}const results=searchRecords(q,cat);box.innerHTML=results.length?`<div class="muted">${results.length} نتیجه${results.length===100?' (نمایش حداکثر ۱۰۰ مورد)':''}</div><div class="search-list">${results.map(r=>`<button class="search-result" data-search-kind="${r.kind}" data-search-id="${esc(r.id)}"><span><b>${esc(r.title)}</b><small>${esc(r.label)} · ${esc(r.detail)}</small></span><span class="search-open">بازکردن ←</span></button>`).join('')}</div>`:'<div class="empty">نتیجه‌ای پیدا نشد.</div>'}
const views={dashboard,search:searchPage,products,customers,orders,finance,expenses,tools,suppliers,reminders,tasks,reports,settings};
function render(){nav();$('title').textContent=({dashboard:'داشبورد',search:'جستجو',products:'محصولات و انبار',customers:'مشتریان',orders:'سفارش‌ها و پروژه‌ها',finance:'مالی، صندوق و بانک',expenses:'هزینه‌ها',tools:'ابزارهای کارگاه',suppliers:'تأمین‌کنندگان',reminders:'تقویم و یادآوری',tasks:'کارهای کارگاه',reports:'گزارش‌ها',settings:'تنظیمات و پشتیبان'})[page];$('view').innerHTML=views[page]();alerts();bind();translateDom();if(page==='reports'){drawReportChart();$('chart-type')?.addEventListener('change',drawReportChart);$('chart-metric')?.addEventListener('change',drawReportChart)}if(page==='orders')bindOrderCalculator();applyAppearance()}
function bindOrderCalculator(){const f=$('order-form');if(!f)return;const update=()=>{const q=Number(f.elements.quantity.value||0),u=Number(f.elements.unitPrice.value||0),pct=Math.min(100,Math.max(0,Number(f.elements.discountPercent.value||0))),cost=Number(f.elements.productionCost.value||0),sub=q*u,disc=Math.round(sub*pct/100),total=Math.max(0,sub-disc);const el=$('order-calculation');if(el)el.innerHTML=`جمع جزء: <b>${fmt(sub)}</b> · تخفیف ${pct}%: <b>${fmt(disc)}</b> · مبلغ نهایی: <b>${fmt(total)}</b> · سود برآوردی: <b>${fmt(total-cost)}</b>`};['quantity','unitPrice','discountPercent','productionCost'].forEach(n=>f.elements[n]?.addEventListener('input',update));if(editOrderId){const o=db.orders.find(x=>x.id===editOrderId);if(o){['customerId','productId','title','orderDate','quantity','unitPrice','discountPercent','productionCost','dueDate','status'].forEach(k=>{if(f.elements[k])f.elements[k].value=o[k]??''})}}update()}
function formData(f){return Object.fromEntries(new FormData(f))}
function printInvoice(o){const c=db.customers.find(x=>x.id===o.customerId)||{},paid=sum(db.payments.filter(p=>p.customerId===o.customerId&&(p.orderId===o.id||p.description?.includes(o.code))&&p.kind==='receipt'),p=>p.amount)-sum(db.payments.filter(p=>p.customerId===o.customerId&&(p.orderId===o.id||p.description?.includes(o.code))&&p.kind==='refund'),p=>p.amount),subtotal=Number(o.subtotal??(o.quantity*o.unitPrice)),discount=Number(o.discount||0),total=Number(o.total||0),profit=Number(o.profit??(total-o.productionCost));const w=window.open('','_blank','width=900,height=700');if(!w){toast('اجازه بازشدن پنجره چاپ را بده.');return}w.document.write(`<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>فاکتور ${esc(o.code)}</title><style>body{font-family:Tahoma,sans-serif;color:#17212b;padding:32px}header{display:flex;justify-content:space-between;border-bottom:3px solid #167e83;padding-bottom:16px}h1{font-size:24px}small{color:#64748b}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:22px 0}.box{border:1px solid #cbd5e1;border-radius:8px;padding:12px}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{border:1px solid #cbd5e1;padding:12px;text-align:right}th{background:#edf5f5}.totals{width:340px;margin-right:auto}.totals div{display:flex;justify-content:space-between;padding:7px;border-bottom:1px solid #ddd}.grand{font-size:19px;font-weight:bold;color:#087e83}.sign{display:flex;justify-content:space-between;margin-top:70px}.foot{margin-top:35px;text-align:center;color:#64748b;font-size:11px}@media print{button{display:none}}</style></head><body><header><div><h1>${esc(db.settings.companyName||'هەوراز')}</h1><div>${esc(db.settings.companyAddress||'')}</div><div>${esc(db.settings.companyPhone||'')}</div><div>شناسه مالیاتی: ${esc(db.settings.taxId||'—')}</div></div><div><h1>فاکتور فروش</h1><b>${esc(o.code)}</b><p>تاریخ: ${esc(o.orderDate||o.createdAt?.slice(0,10)||today())}</p></div></header><div class="meta"><div class="box"><b>صورتحساب برای:</b><p>${esc(c.name||'—')}</p><p>موبایل: ${esc(c.phone||'—')}</p><p>نشانی: ${esc(c.address||'—')}</p></div><div class="box"><b>اطلاعات سفارش:</b><p>موعد تحویل: ${esc(o.dueDate||'—')}</p><p>وضعیت: ${esc(statusName(o.status))}</p><p>شرح: ${esc(o.title)}</p></div></div><table><thead><tr><th>شرح کالا / خدمات</th><th>تعداد</th><th>قیمت واحد</th><th>جمع</th></tr></thead><tbody><tr><td>${esc(o.title)}</td><td>${o.quantity}</td><td>${fmt(o.unitPrice)}</td><td>${fmt(subtotal)}</td></tr></tbody></table><div class="totals"><div><span>جمع جزء</span><b>${fmt(subtotal)}</b></div><div><span>تخفیف (${Number(o.discountPercent||0)}٪)</span><b>${fmt(discount)}</b></div><div class="grand"><span>مبلغ قابل پرداخت</span><b>${fmt(total)}</b></div><div><span>پیش‌پرداخت ثبت‌شده</span><b>${fmt(paid)}</b></div><div><span>مانده این فاکتور*</span><b>${fmt(Math.max(0,total-paid))}</b></div></div><div class="sign"><div>مهر و امضای فروشنده</div><div>امضای مشتری</div></div><div class="foot">این قالب، فاکتور چاپی قابل ویرایش است و به‌تنهایی تأییدیه رسمی مالیاتی محسوب نمی‌شود. *مانده بر اساس پرداخت‌های مرتبط‌شده با کد سفارش محاسبه می‌شود.</div><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close()}
function bind(){
 if(page==='search'){const inp=$('global-search'),cat=$('search-category');inp?.addEventListener('input',drawSearchResults);cat?.addEventListener('change',drawSearchResults);$('clear-search')?.addEventListener('click',()=>{inp.value='';cat.value='all';drawSearchResults();inp.focus()});$('search-results')?.addEventListener('click',e=>{const b=e.target.closest('[data-search-kind]');if(!b)return;const map={products:'products',customers:'customers',orders:'orders',expenses:'expenses',suppliers:'suppliers',tools:'tools',tasks:'tasks',reminders:'reminders'};page=map[b.dataset.searchKind]||'dashboard';editId=null;editOrderId=null;render();toast('بخش مرتبط باز شد؛ برای یافتن مورد، فهرست همان بخش را بررسی کن.')});}
 $('nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;editId=null;editOrderId=null;render()}};
 $('view').onclick=async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.clear){$(b.dataset.clear)?.reset();return}
  if(b.dataset.editOrder){editOrderId=b.dataset.editOrder;page='orders';render();return}
  if(b.dataset.taskDone){const t=db.tasks.find(x=>x.id===b.dataset.taskDone);if(t){t.status=t.status==='done'?'open':t.status==='open'?'doing':'done';await save();render()}return}
  if(b.dataset.taskDel){if(confirm('این کار حذف شود؟')){db.tasks=db.tasks.filter(x=>x.id!==b.dataset.taskDel);await save();render()}return}
  if(b.dataset.edit){const kind=b.dataset.edit,id=b.dataset.id;const arr={product:db.products,customer:db.customers}[kind];const item=arr.find(x=>x.id===id);if(!item)return;const f=$(kind+'-form');Object.entries(item).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v});editId=id;toast('اطلاعات برای ویرایش در فرم قرار گرفت.');return}
  if(b.dataset.del==='product'){const p=db.products.find(x=>x.id===b.dataset.id);if(db.orders.some(o=>o.productId===p.id))return toast('این محصول در سفارش‌ها استفاده شده و حذف نمی‌شود.');if(confirm('محصول حذف شود؟')){db.products=db.products.filter(x=>x.id!==p.id);audit('delete','product',p.id);await save();render()}return}
  if(b.dataset.del==='account'){if(db.payments.some(p=>p.accountId===b.dataset.id)||db.expenses.some(x=>x.accountId===b.dataset.id))return toast('این حساب سابقه تراکنش دارد و حذف نمی‌شود.');if(confirm('حساب حذف شود؟')){db.accounts=db.accounts.filter(a=>a.id!==b.dataset.id);await save();render()}return}
  if(b.dataset.status){const o=db.orders.find(x=>x.id===b.dataset.status);const statuses=['registered','production','ready','delivered','cancelled'];const next=statuses[(statuses.indexOf(o.status)+1)%statuses.length];if(next==='cancelled'&&db.payments.some(p=>p.customerId===o.customerId&&p.description?.includes(o.code)))return toast('برای این سفارش پرداخت ثبت شده؛ ابتدا وضعیت مالی آن را بررسی کن.');if(next==='cancelled'&& !confirm('سفارش لغو شود؟ موجودی محصول به انبار برمی‌گردد.'))return;if(next==='cancelled'&&o.productId){const p=db.products.find(x=>x.id===o.productId);if(p)p.quantity+=o.quantity}if(o.status==='cancelled'&&next!=='cancelled'&&o.productId){const p=db.products.find(x=>x.id===o.productId);if(p&&p.quantity<o.quantity)return toast('موجودی کافی برای فعال‌کردن دوباره سفارش وجود ندارد.');if(p)p.quantity-=o.quantity}o.status=next;audit('status-change','order',o.id,next);await save();render();return}
  if(b.dataset.done){const x=db.reminders.find(x=>x.id===b.dataset.done);x.done=!x.done;await save();render();return}
  if(b.dataset.invoice){const o=db.orders.find(x=>x.id===b.dataset.invoice);printInvoice(o);return}
  if(b.dataset.csv)csv(b.dataset.csv);
 };
 const handlers={
 'product-form':async d=>{const p={id:editId||uid(),...d,quantity:num(d.quantity),buyPrice:num(d.buyPrice),sellPrice:num(d.sellPrice),updatedAt:new Date().toISOString()};if(editId){const i=db.products.findIndex(x=>x.id===editId);db.products[i]=p;audit('update','product',p.id)}else{db.products.push(p);audit('create','product',p.id)}editId=null;},
 'customer-form':async d=>{const c={id:editId||uid(),...d,updatedAt:new Date().toISOString()};if(editId){db.customers[db.customers.findIndex(x=>x.id===editId)]=c;audit('update','customer',c.id)}else{db.customers.push(c);audit('create','customer',c.id)}editId=null;},
 'order-form':async d=>{const qty=num(d.quantity),unit=num(d.unitPrice),pct=Math.min(100,Math.max(0,Number(d.discountPercent||0))),subtotal=qty*unit,discount=Math.round(subtotal*pct/100),total=subtotal-discount,productionCost=num(d.productionCost||0);if(!Number.isSafeInteger(total)||total<0)throw Error('مبلغ نهایی نامعتبر است.');if(!db.customers.some(c=>c.id===d.customerId))throw Error('مشتری را انتخاب کن.');const old=editOrderId?db.orders.find(x=>x.id===editOrderId):null;if(!old&&d.status==='cancelled')throw Error('سفارش جدید را نمی‌توان با وضعیت لغوشده ثبت کرد.');if(old?.status==='cancelled')throw Error('سفارش لغوشده را ویرایش نکن؛ سفارش تازه بساز.');if(old&&old.customerId!==d.customerId&&db.payments.some(x=>x.orderId===old.id||x.description?.includes(old.code)))throw Error('این سفارش پرداخت مرتبط دارد؛ مشتری آن را تغییر نده.');if(old?.productId){const op=db.products.find(x=>x.id===old.productId);if(op)op.quantity+=old.quantity}const p=db.products.find(x=>x.id===d.productId);if(p&&p.quantity<qty){if(old?.productId){const op=db.products.find(x=>x.id===old.productId);if(op)op.quantity-=old.quantity}throw Error('موجودی کافی نیست.')}const paid=num(d.initialPayment||0);if(!old&&paid>total)throw Error('پیش‌پرداخت از مبلغ سفارش بیشتر است.');if(p&&d.status!=='cancelled')p.quantity-=qty;const o={...(old||{}),id:old?.id||uid(),code:old?.code||'HZ-'+Date.now().toString().slice(-8),customerId:d.customerId,productId:d.productId||null,title:d.title,quantity:qty,unitPrice:unit,subtotal,discountPercent:pct,discount,total,productionCost,profit:total-productionCost,orderDate:d.orderDate||today(),dueDate:d.dueDate,status:d.status||'registered',createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};if(old){db.orders[db.orders.findIndex(x=>x.id===old.id)]=o;audit('update','order',o.id)}else{db.orders.push(o);if(paid)db.payments.push({id:uid(),customerId:o.customerId,accountId:'cash',kind:'receipt',amount:paid,date:today(),description:'پیش‌پرداخت سفارش '+o.code});audit('create','order',o.id)}editOrderId=null;},
 'payment-form':async d=>{const amount=num(d.amount);if(!db.customers.some(c=>c.id===d.customerId))throw Error('مشتری نامعتبر است.');if(!db.accounts.some(a=>a.id===d.accountId))throw Error('حساب نامعتبر است.');if(d.kind==='refund'&&amount>Math.max(0,-customerBalance(d.customerId)))throw Error('مبلغ بازپرداخت از بستانکاری مشتری بیشتر است.');const linked=d.orderId?db.orders.find(o=>o.id===d.orderId):null;if(linked&&linked.customerId!==d.customerId)throw Error('سفارش انتخابی متعلق به این مشتری نیست.');db.payments.push({id:uid(),...d,amount,date:d.date||today(),description:[d.description,linked?.code].filter(Boolean).join(' · ')});audit('create','payment',d.id||'new')},
 'account-form':async d=>{db.accounts.push({id:uid(),...d,opening:num(d.opening||0)});audit('create','account',d.name)},
 'expense-form':async d=>{const amount=num(d.amount);if(accountBalance(d.accountId)<amount)throw Error('موجودی حساب برای این هزینه کافی نیست.');db.expenses.push({id:uid(),...d,amount});audit('create','expense',d.title)},
 'tool-form':async d=>{db.tools.push({id:uid(),...d,price:num(d.price||0)});audit('create','tool',d.name)},
 'supplier-form':async d=>{db.suppliers.push({id:uid(),...d});audit('create','supplier',d.name)},
 'reminder-form':async d=>{db.reminders.push({id:uid(),...d,done:false});audit('create','reminder',d.title)},
 'task-form':async d=>{db.tasks.push({id:uid(),...d,createdAt:new Date().toISOString()});audit('create','task',d.title)},
 'settings-form':async d=>{db.settings.currency=d.currency;db.settings.lowStock=num(d.lowStock);db.settings.language=d.language;db.settings.theme=d.theme;db.settings.background=d.background;db.settings.iconStyle=d.iconStyle;db.settings.fontScale=num(d.fontScale);db.settings.iconScale=num(d.iconScale);applyAppearance()},
 'business-form':async d=>{db.settings.companyName=d.companyName;db.settings.companyPhone=d.companyPhone;db.settings.companyAddress=d.companyAddress;db.settings.taxId=d.taxId},
 'password-form':async d=>{if(!await checkPassword(d.currentPassword))throw Error('رمز فعلی درست نیست.');if(d.newPassword.length<8)throw Error('رمز جدید باید دست‌کم ۸ نویسه باشد.');if(d.newPassword!==d.confirmPassword)throw Error('تکرار رمز جدید یکسان نیست.');const h=await makePasswordHash(d.newPassword);db.settings.authSalt=h.salt;db.settings.authHash=h.hash;sessionStorage.setItem('hawraz_unlocked','yes')} 
 };
 Object.entries(handlers).forEach(([id,fn])=>{const f=$(id);if(!f)return;if(id==='settings-form'){['currency','lowStock','language','theme','background','iconStyle','fontScale','iconScale'].forEach(k=>{if(f.elements[k])f.elements[k].value=db.settings[k]??EMPTY.settings[k]})}if(id==='business-form'){['companyName','companyPhone','taxId','companyAddress'].forEach(k=>{if(f.elements[k])f.elements[k].value=db.settings[k]||''})}f.onsubmit=async e=>{e.preventDefault();try{await fn(formData(f));await save();toast('با موفقیت ذخیره شد.');editId=null;render()}catch(err){toast(err.message||'خطا در ذخیره اطلاعات')}}});
 $('backup2')?.addEventListener('click',backup);$('backup-encrypted')?.addEventListener('click',encryptedBackup);$('restore')?.addEventListener('change',restore);
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backup(){const payload={format:'HAWRAZ_LOCAL_BACKUP',version:1,createdAt:new Date().toISOString(),data:db};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`HAWRAZ-backup-${today()}.json`);toast('فایل پشتیبان ساخته شد.')}
async function encryptedBackup(){if(!crypto.subtle)return toast('رمزگذاری در این محیط پشتیبانی نمی‌شود.');const pass=prompt('برای رمزگذاری پشتیبان یک گذرواژه قوی وارد کن:');if(!pass||pass.length<10)return toast('گذرواژه باید حداقل ۱۰ نویسه باشد.');const enc=new TextEncoder(),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const material=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt']);const plain=enc.encode(JSON.stringify({format:'HAWRAZ_LOCAL_BACKUP',version:1,createdAt:new Date().toISOString(),data:db}));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);const pack={format:'HAWRAZ_ENCRYPTED_BACKUP',version:1,salt:Array.from(salt),iv:Array.from(iv),cipher:Array.from(new Uint8Array(cipher))};download(new Blob([JSON.stringify(pack)],{type:'application/json'}),`HAWRAZ-encrypted-${today()}.json`);toast('پشتیبان رمزگذاری‌شده ساخته شد؛ گذرواژه را گم نکن.')}
async function decryptBackup(pack,pass){const enc=new TextEncoder(),salt=new Uint8Array(pack.salt),iv=new Uint8Array(pack.iv),cipher=new Uint8Array(pack.cipher);const material=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);const key=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,cipher);return JSON.parse(new TextDecoder().decode(plain))}

async function restore(e){const f=e.target.files[0];if(!f)return;try{let x=JSON.parse(await f.text());if(x.format==='HAWRAZ_ENCRYPTED_BACKUP'){const pass=prompt('گذرواژه پشتیبان را وارد کن:');if(!pass)throw Error('گذرواژه وارد نشد.');x=await decryptBackup(x,pass)}if(x.format!=='HAWRAZ_LOCAL_BACKUP'||!x.data||!Array.isArray(x.data.products)||!Array.isArray(x.data.customers)||!Array.isArray(x.data.orders))throw Error('ساختار فایل پشتیبان معتبر نیست.');if(!confirm('تمام اطلاعات فعلی این دستگاه با فایل پشتیبان جایگزین شود؟ ابتدا از اطلاعات فعلی پشتیبان گرفته‌ای؟'))return;db={...structuredClone(EMPTY),...x.data};await save();toast('بازیابی انجام شد.');render()}catch(err){toast(err.message)}finally{e.target.value=''}}
function csv(kind){const rows=kind==='orders'?[['code','customer','title','quantity','total','status','dueDate'],...db.orders.map(o=>[o.code,db.customers.find(c=>c.id===o.customerId)?.name,o.title,o.quantity,o.total,o.status,o.dueDate])]:[['name','phone','address','orders','balance'],...db.customers.map(c=>[c.name,c.phone,c.address,customerOrders(c.id).length,customerBalance(c.id)])];const content='\\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\\r\\n');download(new Blob([content],{type:'text/csv;charset=utf-8'}),`HAWRAZ-${kind}-${today()}.csv`)}
$('backup').onclick=backup;$('printCurrent')?.addEventListener('click',printCurrent);
init().catch(e=>{console.error(e);$('view').innerHTML='<div class="notice">پایگاه داده محلی باز نشد. لطفاً برنامه را از طریق سرور محلی اجرا کن، نه با بازکردن مستقیم فایل HTML.</div>'});
